def parse(
    data: str,
    raw: bool = False,
    quiet: bool = False
) -> List[Dict]:
    """
    Main text parsing function

    Parameters:

        data:        (string)  text data to parse
        raw:         (boolean) unprocessed output if True
        quiet:       (boolean) suppress warning messages if True

    Returns:

        List of Dictionaries. Raw or processed structured data.
    """
    jc.utils.compatibility(__name__, info.compatible, quiet)
    jc.utils.input_type_check(data)

    raw_output = []
    cleandata = list(filter(None, data.splitlines()))

    if jc.utils.has_data(data):

        # remove final Entries row if -v was used
        if cleandata[-1].startswith('Entries:'):
            cleandata.pop(-1)

        # detect if freebsd/osx style was used
        if cleandata[0][-1] == ']':
            for line in cleandata:
                splitline = line.split()
                output_line: Dict[str, Any] = {
                    'name': splitline[0],
                    'address': splitline[1].lstrip('(').rstrip(')'),
                    'hwtype': splitline[-1].lstrip('[').rstrip(']'),
                    'hwaddress': splitline[3],
                    'iface': splitline[5]
                }

                if 'permanent' in splitline:
                    output_line['permanent'] = True
                else:
                    output_line['permanent'] = False

                if 'expires' in splitline:
                    output_line['expires'] = splitline[-3]

                raw_output.append(output_line)

        # detect if linux style was used
        elif cleandata[0].startswith('Address'):

            # fix header row to change Flags Mask to flags_mask
            cleandata[0] = cleandata[0].replace('Flags Mask', 'flags_mask')
            cleandata[0] = cleandata[0].lower()

            raw_output = jc.parsers.universal.simple_table_parse(cleandata)

        # otherwise, try bsd style
        else:
            for line in cleandata:
                splitline = line.split()

                # Ignore AIX bucket information
                if 'bucket:' in splitline[0]:
                    continue
                elif 'There' in splitline[0] and 'are' in splitline[1]:
                    continue

                # AIX uses (incomplete)
                elif '<incomplete>' not in splitline and '(incomplete)' not in splitline:
                    output_line = {
                        'name': splitline[0],
                        'address': splitline[1].lstrip('(').rstrip(')'),
                        'hwtype': splitline[4].lstrip('[').rstrip(']'),
                        'hwaddress': splitline[3],
                    }
                    # Handle permanence and ignore interface in AIX
                    if 'permanent' in splitline:
                        output_line['permanent'] = True
                    elif 'in' not in splitline[6]: # AIX doesn't show interface
                        output_line['iface'] = splitline[6]

                else:
                    output_line = {
                        'name': splitline[0],
                        'address': splitline[1].lstrip('(').rstrip(')'),
                        'hwtype': None,
                        'hwaddress': None,
                    }
                    # AIX doesn't show interface
                    if len(splitline) >= 5:
                        output_line['iface'] = splitline[5]

                raw_output.append(output_line)

    return raw_output if raw else _process(raw_output)

def parse(
    data: str,
    raw: bool = False,
    quiet: bool = False
) -> JSONDictType:
    """
    Main text parsing function

    Parameters:

        data:        (string)  text data to parse
        raw:         (boolean) unprocessed output if True
        quiet:       (boolean) suppress warning messages if True

    Returns:

        Dictionary. Raw or processed structured data.
    """
    jc.utils.compatibility(__name__, info.compatible, quiet)
    jc.utils.input_type_check(data)

    raw_output: Dict = {}
    cert_list: List = []
    cert_dict: Dict = {}
    acct_dict: Dict = {}
    cmd_option = ''

    if jc.utils.has_data(data):

        cert_pattern = re.compile(r'^Found the following (matching )?certs:\r?$', re.MULTILINE)

        if re.search(cert_pattern, data):
            cmd_option = 'certificates'
        else:
            cmd_option = 'account'

        for line in filter(None, data.splitlines()):

            if cmd_option == 'certificates':
                if line.startswith('  Certificate Name:'):
                    if cert_dict:
                        cert_list.append(cert_dict)
                        cert_dict = {}

                    cert_dict['name'] = line.split()[-1]

                if line.startswith('    Serial Number:'):
                    cert_dict['serial_number'] = line.split()[-1]

                if line.startswith('    Key Type:'):
                    cert_dict['key_type'] = line.split(': ', maxsplit=1)[1]

                if line.startswith('    Domains:'):
                    splitline = line.split(': ', maxsplit=1)[1]
                    cert_dict['domains'] = splitline.split()

                if line.startswith('    Expiry Date:'):
                    splitline = line.split(': ', maxsplit=1)[1]
                    cert_datetime = splitline.split('(')[0]
                    validity = splitline.split('(')[1]
                    cert_dict['expiration_date'] = cert_datetime.strip()
                    cert_dict['validity'] = validity[:-1].replace('VALID: ', '')

                if line.startswith('    Certificate Path:'):
                    cert_dict['certificate_path'] = line.split(': ', maxsplit=1)[1]

                if line.startswith('    Private Key Path:'):
                    cert_dict['private_key_path'] = line.split(': ', maxsplit=1)[1]

            if cmd_option == 'account':
                if line.startswith('Account details for server'):
                    acct_dict['server'] = line.split()[-1][:-1]

                if line.startswith('  Account URL:'):
                    acct_dict['url'] = line.split()[-1]

                if line.startswith('  Email contact:'):
                    acct_dict['email'] = line.split()[-1]

    if acct_dict:
        raw_output['account'] = acct_dict

    if cert_dict:
        cert_list.append(cert_dict)

    if cert_list:
        raw_output['certificates'] = cert_list

    return raw_output if raw else _process(raw_output)

def parse(
    data: str,
    raw: bool = False,
    quiet: bool = False
) -> List[Dict]:
    """
    Main text parsing function

    Parameters:

        data:        (string)  text data to parse
        raw:         (boolean) unprocessed output if True
        quiet:       (boolean) suppress warning messages if True

    Returns:

        List of Dictionaries. Raw or processed structured data.
    """
    jc.utils.compatibility(__name__, info.compatible, quiet)
    jc.utils.input_type_check(data)

    raw_output: List = []
    output_line: Dict = {}
    message_lines: List[str] = []
    file_list: List[str] = []
    file_stats_list: List[Dict[str, Any]] = []
    numstat_found: bool = False
    patch_lines: List[str] = []

    if jc.utils.has_data(data):

        for line in data.splitlines():
            line_list = line.split(maxsplit=1)

            # oneline style
            if not line.startswith(' ') and line_list and _is_commit_hash(line_list[0]):
                if output_line:
                    if file_list:
                        output_line['stats']['files'] = file_list

                    if file_stats_list:
                        output_line['stats']['file_stats'] = file_stats_list

                    if patch_lines:
                        output_line['patch'] = '\n'.join(patch_lines)

                    raw_output.append(output_line)
                    output_line = {}
                    message_lines = []
                    file_list = []
                    file_stats_list = []
                    numstat_found = False
                    patch_lines = []
                output_line = {
                    'commit': line_list[0],
                    'message': line_list[1]
                }
                continue

            # all other styles
            if line.startswith('commit '):
                if output_line:
                    if message_lines:
                        output_line['message'] = '\n'.join(message_lines)

                    if file_list:
                        output_line['stats']['files'] = file_list

                    if file_stats_list:
                        output_line['stats']['file_stats'] = file_stats_list

                    if patch_lines:
                        output_line['patch'] = '\n'.join(patch_lines)

                    raw_output.append(output_line)
                    output_line = {}
                    message_lines = []
                    file_list = []
                    file_stats_list = []
                    numstat_found = False
                    patch_lines = []
                output_line['commit'] = line_list[1]
                continue

            if line.startswith('Merge: '):
                output_line['merge'] = line_list[1]
                continue

            if line.startswith('Author: '):
                output_line['author'], output_line['author_email'] = _parse_name_email(line_list[1])
                continue

            if line.startswith('Date: '):
                output_line['date'] = line_list[1]
                continue

            if line.startswith('AuthorDate: '):
                output_line['date'] = line_list[1]
                continue

            if line.startswith('CommitDate: '):
                output_line['commit_by_date'] = line_list[1]
                continue

            if line.startswith('Commit: '):
                output_line['commit_by'], output_line['commit_by_email'] = _parse_name_email(line_list[1])
                continue

            if patch_start_pattern.match(line) or patch_lines:
                # this is the commit patch. Everything from the first diff
                # header up to the next commit is kept verbatim, including
                # context lines and binary file notices. Any blank line here
                # is the separator before the next commit.
                if line:
                    patch_lines.append(line)
                continue

            if line.startswith('    '):
                message_lines.append(line.strip())
                continue

            numstat = numstat_pattern.match(line)
            if numstat:
                # this is a --numstat line
                file_stats_list.append({
                    'name': numstat['name'],
                    'insertions': numstat['insertions'],
                    'deletions': numstat['deletions']
                })
                file_list.append(numstat['name'])
                output_line.setdefault('stats', {})
                numstat_found = True
                continue

            if line.startswith(' ') and 'changed, ' not in line:
                # this is a file name from `--stat`. Ignore if `--numstat`
                # output was already found for this commit since it is
                # more detailed.
                if numstat_found:
                    continue

                file_line_split = line.split('|')
                file_name = file_line_split[0].strip()
                file_list.append(file_name)

                if len(file_line_split) > 1:
                    file_stats = file_line_split[1].strip()
                    lines_changed_str = file_stats.split(' ')
                    lines_changed_count_str = lines_changed_str[0].strip()

                file_stat = {}
                file_stat["name"] = file_name
                file_stat["lines_changed"] = lines_changed_count_str
                file_stats_list.append(file_stat)
                continue

            if line.startswith(' ') and 'changed, ' in line:
                # this is the stat summary
                changes = changes_pattern.match(line)
                if changes:
                    files = changes['files']
                    insertions = changes['insertions']
                    deletions = changes['deletions']

                output_line['stats'] = {
                    'files_changed': files or '0',
                    'insertions': insertions or '0',
                    'deletions':  deletions or '0'
                }

    if output_line:
        if message_lines:
            output_line['message'] = '\n'.join(message_lines)

        if file_list:
            output_line['stats']['files'] = file_list

        if file_stats_list:
            output_line['stats']['file_stats'] = file_stats_list

        if patch_lines:
            output_line['patch'] = '\n'.join(patch_lines)

        raw_output.append(output_line)

    return raw_output if raw else _process(raw_output)

@add_jc_meta
def parse(
    data: Iterable[str],
    raw: bool = False,
    quiet: bool = False,
    ignore_exceptions: bool = False
) -> Union[Iterable[Dict], tuple]:
    """
    Main text parsing generator function. Returns an iterable object.

    Parameters:

        data:              (iterable)  line-based text data to parse
                                       (e.g. sys.stdin or str.splitlines())

        raw:               (boolean)   unprocessed output if True
        quiet:             (boolean)   suppress warning messages if True
        ignore_exceptions: (boolean)   ignore parsing exceptions if True


    Returns:

        Iterable of Dictionaries
    """
    jc.utils.compatibility(__name__, info.compatible, quiet)
    streaming_input_type_check(data)

    output_line: Dict = {}
    message_lines: List[str] = []
    file_list: List[str] = []
    file_stats_list: List[Dict[str, Any]] = []
    numstat_found: bool = False
    patch_lines: List[str] = []

    for line in data:
        try:
            streaming_line_input_type_check(line)

            if line == '' or line == '\n':
                continue

            line_list = line.rstrip().split(maxsplit=1)

            # oneline style
            if not line.startswith(' ') and line_list and _is_commit_hash(line_list[0]):
                if output_line:
                    if file_list:
                        output_line['stats']['files'] = file_list

                    if file_stats_list:
                        output_line['stats']['file_stats'] = file_stats_list

                    if patch_lines:
                        output_line['patch'] = '\n'.join(patch_lines)

                    yield output_line if raw else _process(output_line)

                    output_line = {}
                    message_lines = []
                    file_list = []
                    file_stats_list = []
                    numstat_found = False
                    patch_lines = []
                output_line = {
                    'commit': line_list[0],
                    'message': line_list[1]
                }
                continue

            # all other styles
            if line.startswith('commit '):
                if output_line:
                    if message_lines:
                        output_line['message'] = '\n'.join(message_lines)

                    if file_list:
                        output_line['stats']['files'] = file_list

                    if file_stats_list:
                        output_line['stats']['file_stats'] = file_stats_list

                    if patch_lines:
                        output_line['patch'] = '\n'.join(patch_lines)

                    yield output_line if raw else _process(output_line)

                    output_line = {}
                    message_lines = []
                    file_list = []
                    file_stats_list = []
                    numstat_found = False
                    patch_lines = []
                output_line['commit'] = line_list[1]
                continue

            if line.startswith('Merge: '):
                output_line['merge'] = line_list[1]
                continue

            if line.startswith('Author: '):
                output_line['author'], output_line['author_email'] = _parse_name_email(line_list[1])
                continue

            if line.startswith('Date: '):
                output_line['date'] = line_list[1]
                continue

            if line.startswith('AuthorDate: '):
                output_line['date'] = line_list[1]
                continue

            if line.startswith('CommitDate: '):
                output_line['commit_by_date'] = line_list[1]
                continue

            if line.startswith('Commit: '):
                output_line['commit_by'], output_line['commit_by_email'] = _parse_name_email(line_list[1])
                continue

            if patch_start_pattern.match(line) or patch_lines:
                # this is the commit patch. Everything from the first diff
                # header up to the next commit is kept verbatim, including
                # context lines and binary file notices.
                patch_lines.append(line.rstrip('\r\n'))
                continue

            if line.startswith('    '):
                message_lines.append(line.strip())
                continue

            numstat = numstat_pattern.match(line)
            if numstat:
                # this is a --numstat line
                file_stats_list.append({
                    'name': numstat['name'],
                    'insertions': numstat['insertions'],
                    'deletions': numstat['deletions']
                })
                file_list.append(numstat['name'])
                output_line.setdefault('stats', {})
                numstat_found = True
                continue

            if line.startswith(' ') and 'changed, ' not in line:
                # this is a file name from `--stat`. Ignore if `--numstat`
                # output was already found for this commit since it is
                # more detailed.
                if numstat_found:
                    continue

                file_line_split = line.split('|')
                file_name = file_line_split[0].strip()
                file_list.append(file_name)

                if len(file_line_split) > 1:
                    file_stats = file_line_split[1].strip()
                    lines_changed_str = file_stats.split(' ')
                    lines_changed_count_str = lines_changed_str[0].strip()

                file_stat = {}
                file_stat["name"] = file_name
                file_stat["lines_changed"] = lines_changed_count_str
                file_stats_list.append(file_stat)
                continue

            if line.startswith(' ') and 'changed, ' in line:
                # this is the stat summary
                changes = changes_pattern.match(line)
                if changes:
                    files = changes['files']
                    insertions = changes['insertions']
                    deletions = changes['deletions']

                output_line['stats'] = {
                    'files_changed': files or '0',
                    'insertions': insertions or '0',
                    'deletions':  deletions or '0'
                }
                continue

            if line.rstrip('\r\n') == '---':
                # separator between the commit message and the --stat block
                # when --patch is also requested
                continue

            raise ParseError('Not git_log_s data')

        except Exception as e:
            yield raise_or_yield(ignore_exceptions, e, line)

    try:
        if output_line:
            if message_lines:
                output_line['message'] = '\n'.join(message_lines)

            if file_list:
                output_line['stats']['files'] = file_list

            if file_stats_list:
                output_line['stats']['file_stats'] = file_stats_list

            if patch_lines:
                output_line['patch'] = '\n'.join(patch_lines)

            yield output_line if raw else _process(output_line)

    except Exception as e:
        yield raise_or_yield(ignore_exceptions, e, line)

    return None

