def parse(data, raw=False, quiet=False):
    """
    Main text parsing function

    Parameters:

        data:        (string)  text data to parse
        raw:         (boolean) unprocessed output if True
        quiet:       (boolean) suppress warning messages if True

    Returns:

        List of Json objects if data is processed and Raw data if raw = true.
    """
    jc.utils.compatibility(__name__, info.compatible, quiet)
    jc.utils.input_type_check(data)

    structure = {}
    items = []
    lines = data.splitlines()
    index = 0
    place = 0
    inc = 0

    if not jc.utils.has_data(data):
        return items

    for line in lines:
        temp = line.split()
        for word in temp:
            if word == 'via':
                y = {'via': temp[place + 1]}
                place += 1
                structure.update(y)
            elif word == 'dev':
                y = {'dev': temp[place + 1]}
                place += 1
                structure.update(y)
            elif word == 'metric':
                if raw:
                    y = {'metric': temp[place + 1]}
                else:
                    y = {'metric': jc.utils.convert_to_int(temp[place+1])}
                place += 1
                structure.update(y)
            elif word == 'proto':
                y = {'proto': temp[place + 1]}
                place += 1
                structure.update(y)
            elif word == 'scope':
                y = {'scope': temp[place + 1]}
                place += 1
                structure.update(y)
            elif word == 'src':
                y = {'src': temp[place + 1]}
                place += 1
                structure.update(y)
            elif word == 'status':
                y = {'status': temp[place + 1]}
                place += 1
                structure.update(y)
            elif word == 'default':
                y = {'ip': 'default'}
                place += 1
                structure.update(y)
            elif word == 'linkdown':
                y = {'status': 'linkdown'}
                place += 1
                structure.update(y)
            else:
                y = {'ip': temp[0]}
                place += 1
                structure.update(y)
        if y.get("ip") != "":
            items.append(structure)
        structure = {}
        place = 0
        index += 1
        inc += 1

    return items

def parse(
    data: str,
    raw: bool = False,
    quiet: bool = False
) -> List[Dict]:
    """
    Main text parsing function

    Parameters:

        data:        (string)  text data to parse
        raw:         (boolean) unprocessed output if True
        quiet:       (boolean) suppress warning messages if True

    Returns:

        List of Dictionaries. Raw or processed structured data.
    """
    jc.utils.compatibility(__name__, info.compatible, quiet)
    jc.utils.input_type_check(data)

    raw_output: List = []
    output_line = {}

    if jc.utils.has_data(data):
        for line in filter(None, data.splitlines()):
            # ignore any lines with only whitespace
            if not jc.utils.has_data(line):
                continue

            # extended info fields
            if line.lstrip().startswith('#EXTINF:'):
                splitline = line.strip().split(':', maxsplit=1)

                # best-effort to parse additional extended fields
                # if a parsing error occurs, a warning message will be
                # printed to STDERR and `unparsed_info` added
                try:
                    extline = shlex.shlex(splitline[1], posix=True)
                    extline.whitespace_split = True
                    extline.whitespace = ', '  # add comma to whitespace detection
                    extline.quotes = '"'  # remove single quotes
                    extline_list = list(extline)
                    runtime = extline_list.pop(0)
                    display_list = []

                    for item in extline_list:
                        if '=' in item:
                            k, v = item.split('=', maxsplit=1)
                            output_line.update({k: v})

                        else:
                            display_list.append(item)

                    display = ' '.join(display_list)
                    output_line.update({
                        'runtime': runtime,
                        'display': display
                    })

                except Exception:
                    if not quiet:
                        jc.utils.warning_message([
                            'Not able to parse non-standard extensions in the following line:',
                            line
                        ])
                    output_line = {'unparsed_info': line}

                continue

            # ignore all other extension info (obsolete)
            if line.lstrip().startswith('#'):
                continue

            # any lines left over are paths
            output_line.update(
                {'path': line.strip()}
            )

            raw_output.append(output_line)
            output_line = {}

    return raw_output if raw else _process(raw_output)

def parse_post(raw_data):
    for entry in raw_data:
        # fixup name field in Registered kernel control module
        if 'name' in entry:
            if entry['name']:
                entry['name'] = entry['name'].strip()

        # create network and transport protocol fields
        if 'local_address' in entry:
            if entry['local_address']:
                ladd = entry['local_address'].rsplit('.', maxsplit=1)[0]
                lport = entry['local_address'].rsplit('.', maxsplit=1)[1]
                entry['local_address'] = ladd
                entry['local_port'] = lport

        if 'foreign_address' in entry:
            if entry['foreign_address']:
                fadd = entry['foreign_address'].rsplit('.', maxsplit=1)[0]
                fport = entry['foreign_address'].rsplit('.', maxsplit=1)[1]
                entry['foreign_address'] = fadd
                entry['foreign_port'] = fport

        if 'proto' in entry and 'kind' in entry:
            if entry['kind'] == 'network':
                if entry['proto'] == 'udp46':
                    entry['transport_protocol'] = entry['proto'][:-2]
                elif entry['proto'].startswith('icm'):
                    entry['transport_protocol'] = 'icmp'
                else:
                    entry['transport_protocol'] = entry['proto'][:-1]

                if '6' in entry['proto']:
                    entry['network_protocol'] = 'ipv6'
                else:
                    entry['network_protocol'] = 'ipv4'

        # add route_flags_pretty field
        if 'route_flags' in entry:
            flag_map = {
                '1': 'PROTO1',
                '2': 'PROTO2',
                '3': 'PROTO3',
                'B': 'BLACKHOLE',
                'b': 'BROADCAST',
                'C': 'CLONING',
                'c': 'PRCLONING',
                'D': 'DYNAMIC',
                'G': 'GATEWAY',
                'H': 'HOST',
                'I': 'IFSCOPE',
                'i': 'IFREF',
                'L': 'LLINFO',
                'M': 'MODIFIED',
                'm': 'MULTICAST',
                'R': 'REJECT',
                'r': 'ROUTER',
                'S': 'STATIC',
                'U': 'UP',
                'W': 'WASCLONED',
                'X': 'XRESOLVE',
                'Y': 'PROXY',
            }

            pretty_flags = []

            for flag in entry['route_flags']:
                if flag in flag_map:
                    pretty_flags.append(flag_map[flag])

            entry['route_flags_pretty'] = pretty_flags

        # strip whitespace from beginning and end of all string values
        for item in entry:
            if isinstance(entry[item], str):
                entry[item] = entry[item].strip()

    return raw_data

def parse_post(raw_data):
    # clean up trailing whitespace on each item in each entry
    # flags --- = null
    # program_name - = null
    # split pid and program name and ip addresses and ports
    # create network and transport protocol fields

    for entry in raw_data:
        for item in entry:
            try:
                entry[item] = entry[item].rstrip()
            except (AttributeError):
                # skips trying to rstrip Null entries
                pass

        if 'flags' in entry:
            if entry['flags'] == '---':
                entry['flags'] = None

        if 'program_name' in entry:
            entry['program_name'] = entry['program_name'].strip()
            if entry['program_name'] == '-':
                entry['program_name'] = None

            if entry['program_name']:
                pid = entry['program_name'].split('/', maxsplit=1)[0]
                name = entry['program_name'].split('/', maxsplit=1)[1]
                entry['pid'] = pid
                entry['program_name'] = name

        if 'local_address' in entry:
            if entry['local_address']:
                ladd = entry['local_address'].rsplit(':', maxsplit=1)[0]
                lport = entry['local_address'].rsplit(':', maxsplit=1)[1]
                entry['local_address'] = ladd
                entry['local_port'] = lport

        if 'foreign_address' in entry:
            if entry['foreign_address']:
                fadd = entry['foreign_address'].rsplit(':', maxsplit=1)[0]
                fport = entry['foreign_address'].rsplit(':', maxsplit=1)[1]
                entry['foreign_address'] = fadd
                entry['foreign_port'] = fport

        if 'proto' in entry and 'kind' in entry:
            if entry['kind'] == 'network':
                if 'tcp' in entry['proto']:
                    entry['transport_protocol'] = 'tcp'
                elif 'udp' in entry['proto']:
                    entry['transport_protocol'] = 'udp'
                else:
                    entry['transport_protocol'] = None

                if '6' in entry['proto']:
                    entry['network_protocol'] = 'ipv6'
                else:
                    entry['network_protocol'] = 'ipv4'

        # add route_flags_pretty
        # Flag mapping from https://www.man7.org/linux/man-pages/man8/route.8.html
        if 'route_flags' in entry:
            flag_map = {
                'U': 'UP',
                'H': 'HOST',
                'G': 'GATEWAY',
                'R': 'REINSTATE',
                'D': 'DYNAMIC',
                'M': 'MODIFIED',
                'A': 'ADDRCONF',
                'C': 'CACHE',
                '!': 'REJECT'
            }

            pretty_flags = []

            for flag in entry['route_flags']:
                if flag in flag_map:
                    pretty_flags.append(flag_map[flag])

            entry['route_flags_pretty'] = pretty_flags

    return raw_data

def parse(
    data: str,
    raw: bool = False,
    quiet: bool = False
) -> JSONDictType:
    """
    Main text parsing function

    Parameters:

        data:        (string)  text data to parse
        raw:         (boolean) unprocessed output if True
        quiet:       (boolean) suppress warning messages if True

    Returns:

        Dictionary. Raw or processed structured data.
    """
    jc.utils.compatibility(__name__, info.compatible, quiet)
    jc.utils.input_type_check(data)

    raw_output: Dict = {}
    clients: List[Dict] = []
    routing_table: List[Dict] = []
    global_stats: Dict = {}
    section: str = ''  # clients, routing, stats
    updated: str = ''

    if jc.utils.has_data(data):

        for line in filter(None, data.splitlines()):

            if line.startswith('OpenVPN CLIENT LIST'):
                section = 'clients'
                continue

            if line.startswith('ROUTING TABLE'):
                section = 'routing'
                continue

            if line.startswith('GLOBAL STATS'):
                section = 'stats'
                continue

            if line.startswith('END'):
                break

            if section == 'clients' and line.startswith('Updated,'):
                _, updated = line.split(',', maxsplit=1)
                continue

            if section == 'clients' and line.startswith('Common Name,Real Address,'):
                continue

            if section == 'clients':
                c_name, real_addr, r_bytes, s_bytes, connected = line.split(',', maxsplit=5)
                clients.append(
                    {
                        'common_name': c_name,
                        'real_address': real_addr,
                        'bytes_received': r_bytes,
                        'bytes_sent': s_bytes,
                        'connected_since': connected,
                        'updated': updated
                    }
                )
                continue

            if section == 'routing' and line.startswith('Virtual Address,Common Name,'):
                continue

            if section == 'routing':
                # Virtual Address,Common Name,Real Address,Last Ref
                # 192.168.255.118,baz@example.com,10.10.10.10:63414,Thu Jun 18 08:12:09 2015
                virt_addr, c_name, real_addr, last_ref = line.split(',', maxsplit=4)
                route = {
                    'virtual_address': virt_addr,
                    'common_name': c_name,
                    'real_address': real_addr,
                    'last_reference': last_ref
                }

                # fixup for virtual addresses ending in "C"
                if 'virtual_address' in route:
                    if route['virtual_address'].endswith('C'):
                        route['virtual_address'] = route['virtual_address'][:-1]

                routing_table.append(route)
                continue

            if section == "stats":
                if line.startswith('Max bcast/mcast queue length'):
                    global_stats['max_bcast_mcast_queue_len'] = line.split(',', maxsplit=1)[1]
                    continue

        raw_output['clients'] = clients
        raw_output['routing_table'] = routing_table
        raw_output['global_stats'] = {}
        raw_output['global_stats'].update(global_stats)

    return raw_output if raw else _process(raw_output)

def parse(
    data: str,
    raw: bool = False,
    quiet: bool = False
) -> JSONDictType:
    """
    Main text parsing function

    Parameters:

        data:        (string)  text data to parse
        raw:         (boolean) unprocessed output if True
        quiet:       (boolean) suppress warning messages if True

    Returns:

        Dictionary. Raw or processed structured data.
    """
    jc.utils.compatibility(__name__, info.compatible, quiet)
    jc.utils.input_type_check(data)

    raw_output: Dict = {}
    vdc_obj: Dict = {}
    vendor_id: str = ''
    device_id: str = ''

    class_obj: Dict = {}
    class_id: str = ''
    subclass_id: str = ''

    if jc.utils.has_data(data):

        vdc_header_p = re.compile(r'^(?P<vendor_id>[0-9a-f]{4})\s+(?P<vendor_name>.+)')
        vdc_device_p = re.compile(r'^\t(?P<device_id>[0-9a-f]{4})\s+(?P<device_name>.+)')
        vdc_subvendor_p = re.compile(r'^\t\t(?P<subvendor>[0-9a-f]{4})\s+(?P<subdevice>[0-9a-f]{4})\s+(?P<subsystem_name>.+)')

        class_header_p = re.compile(r'^C\s+(?P<class_id>[0-9a-f]{2})\s+(?P<class_name>.+)')
        class_sub_p = re.compile(r'^\t(?P<subclass_id>[0-9a-f]{2})\s+(?P<subclass_name>.+)')
        class_progif_p = re.compile(r'^\t\t(?P<prog_if_id>[0-9a-f]{2})\s+(?P<prog_if_name>.+)')

        for line in filter(None, data.splitlines()):

            vdc_header = vdc_header_p.match(line)
            vdc_device = vdc_device_p.match(line)
            vdc_subvendor = vdc_subvendor_p.match(line)

            class_header = class_header_p.match(line)
            class_sub = class_sub_p.match(line)
            class_progif = class_progif_p.match(line)

            # Vendors, devices and subsystems
            # Syntax:
            # vendor  vendor_name
            #	device  device_name                       <-- single tab
            #		subvendor subdevice  subsystem_name   <-- two tabs
            # Example:
            # 001c  PEAK-System Technik GmbH
            #     0001  PCAN-PCI CAN-Bus controller
            #         001c 0004  2 Channel CAN Bus SJC1000
            if vdc_header:
                if vdc_obj:
                    if 'vendors' not in raw_output:
                        raw_output['vendors'] = {}
                    raw_output['vendors'][vendor_id] = vdc_obj[vendor_id]
                    vdc_obj = {}

                vendor_id = '_' + vdc_header.groupdict()['vendor_id']
                vdc_obj[vendor_id] = {}
                vdc_obj[vendor_id]['vendor_name'] = vdc_header.groupdict()['vendor_name']
                continue

            if vdc_device:
                device_id = '_' + vdc_device.groupdict()['device_id']
                vdc_obj[vendor_id][device_id] = {}
                vdc_obj[vendor_id][device_id]['device_name'] = vdc_device.groupdict()['device_name']
                continue

            if vdc_subvendor:
                subvendor = '_' + vdc_subvendor.groupdict()['subvendor']
                subdevice = '_' + vdc_subvendor.groupdict()['subdevice']
                if not vdc_obj[vendor_id][device_id].get(subvendor) or not isinstance(vdc_obj[vendor_id][device_id][subvendor], dict):
                    vdc_obj[vendor_id][device_id][subvendor] = {}
                vdc_obj[vendor_id][device_id][subvendor][subdevice] = {}
                vdc_obj[vendor_id][device_id][subvendor][subdevice]['subsystem_name'] = vdc_subvendor.groupdict()['subsystem_name']
                continue

            # List of known device classes, subclasses and programming interfaces
            # Syntax:
            # C class	class_name
            #	subclass	subclass_name       <-- single tab
            #		prog-if  prog-if_name       <-- two tabs
            # Example:
            # C 01  Mass storage controller
            #     01  IDE interface
            #         00  ISA Compatibility mode-only controller
            if class_header:
                if class_obj:
                    if 'classes' not in raw_output:
                        raw_output['classes'] = {}
                    raw_output['classes'][class_id] = class_obj[class_id]
                    class_obj = {}

                class_id = '_' + class_header.groupdict()['class_id']
                class_obj[class_id] = {}
                class_obj[class_id]['class_name'] = class_header.groupdict()['class_name']
                continue

            if class_sub:
                subclass_id = '_' + class_sub.groupdict()['subclass_id']
                class_obj[class_id][subclass_id] = {}
                class_obj[class_id][subclass_id]['subclass_name'] = class_sub.groupdict()['subclass_name']
                continue

            if class_progif:
                prog_if_id = '_' + class_progif.groupdict()['prog_if_id']
                class_obj[class_id][subclass_id][prog_if_id] = class_progif.groupdict()['prog_if_name']
                continue

        if vdc_obj:
            if 'vendors' not in raw_output:
                raw_output['vendors'] = {}
            raw_output['vendors'][vendor_id] = vdc_obj[vendor_id]

        if class_obj:
            if 'classes' not in raw_output:
                raw_output['classes'] = {}
            raw_output['classes'][class_id] = class_obj[class_id]

    return raw_output if raw else _process(raw_output)

def parse(
    data: str,
    raw: bool = False,
    quiet: bool = False
) -> Dict:
    """
    Main text parsing function

    Parameters:

        data:        (string)  text data to parse
        raw:         (boolean) unprocessed output if True
        quiet:       (boolean) suppress warning messages if True

    Returns:

        Dictionary. Raw or processed structured data.
    """
    jc.utils.compatibility(__name__, info.compatible, quiet)
    jc.utils.input_type_check(data)

    raw_output: Dict = {}

    if jc.utils.has_data(data):

        for line in filter(None, data.splitlines()):

            if line.startswith('cpu'):
                split_line = line.split()
                cpu_num = split_line[0]
                raw_output[cpu_num] = {
                    'user': int(split_line[1]),
                    'nice': int(split_line[2]),
                    'system': int(split_line[3]),
                    'idle': int(split_line[4])
                }

                if len(split_line) > 5:
                    raw_output[cpu_num]['iowait'] = int(split_line[5])

                if len(split_line) > 6:
                    raw_output[cpu_num]['irq'] = int(split_line[6])
                    raw_output[cpu_num]['softirq'] = int(split_line[7])

                if len(split_line) > 8:
                    raw_output[cpu_num]['steal'] = int(split_line[8])

                if len(split_line) > 9:
                    raw_output[cpu_num]['guest'] = int(split_line[9])

                if len(split_line) > 10:
                    raw_output[cpu_num]['guest_nice'] = int(split_line[10])

                continue

            if line.startswith('intr '):
                split_line = line.split()
                raw_output['interrupts'] = [int(x) for x in split_line[1:]]
                continue

            if line.startswith('ctxt '):
                raw_output['context_switches'] = int(line.split(maxsplit=1)[1])
                continue

            if line.startswith('btime '):
                raw_output['boot_time'] = int(line.split(maxsplit=1)[1])
                continue

            if line.startswith('processes '):
                raw_output['processes'] = int(line.split(maxsplit=1)[1])
                continue

            if line.startswith('procs_running '):
                raw_output['processes_running'] = int(line.split(maxsplit=1)[1])
                continue

            if line.startswith('procs_blocked '):
                raw_output['processes_blocked'] = int(line.split(maxsplit=1)[1])
                continue

            if line.startswith('softirq '):
                split_line = line.split()
                raw_output['softirq'] = [int(x) for x in split_line[1:]]
                continue

    return raw_output if raw else _process(raw_output)

def parse(
    data: str,
    raw: bool = False,
    quiet: bool = False
) -> List[Dict]:
    """
    Main text parsing function

    Parameters:

        data:        (string)  text data to parse
        raw:         (boolean) unprocessed output if True
        quiet:       (boolean) suppress warning messages if True

    Returns:

        List of Dictionaries. Raw or processed structured data.
    """
    jc.utils.compatibility(__name__, info.compatible, quiet)
    jc.utils.input_type_check(data)

    raw_output: List = []
    output_line: Dict = {}
    node = None
    section = 'stats'    # stats, pages, pagesets
    pageset = None

    if jc.utils.has_data(data):

        for line in filter(None, data.splitlines()):

            if line == '  per-node stats':
                continue

            if line.startswith('Node ') and line.endswith('DMA'):
                if output_line:
                    raw_output.append(output_line)
                    output_line = {}

                section = 'stats'
                _, node, _, zone = line.replace(',', '').split()
                output_line['node'] = int(node)
                output_line[zone] = {}
                continue

            if line.startswith('Node '):
                section = 'stats'

                if pageset:
                    output_line[zone]['pagesets'].append(pageset)
                    pageset = {}

                _, node, _, zone = line.replace(',', '').split()
                output_line['node'] = int(node)
                output_line[zone] = {}
                continue

            if line.startswith('  pages free '):
                section = 'pages'
                output_line[zone]['pages'] = {}
                output_line[zone]['pages']['free'] = int(line.split()[-1])
                continue

            if line.startswith('  pagesets'):
                section = 'pagesets'
                output_line[zone]['pagesets'] = []
                pageset = {}  # type: ignore
                continue

            if section == 'stats':
                key, val = line.split(maxsplit=1)
                output_line[key] = int(val)
                continue

            if section == 'pages' and line.startswith('        protection: '):
                protection = line.replace('(', '').replace(')', '').replace(',', '').split()[1:]
                output_line[zone]['pages']['protection'] = [int(x) for x in protection]
                continue

            if section == 'pages':
                key, val = line.split(maxsplit=1)
                output_line[zone]['pages'][key] = int(val)
                continue

            if section == 'pagesets' and line.startswith('    cpu: '):
                if pageset:
                    output_line[zone]['pagesets'].append(pageset)

                split_line = line.replace(':', '').split(maxsplit=1)
                pageset = {"cpu": int(split_line[1])}
                continue

            if section == 'pagesets':
                key, val = line.split(':', maxsplit=1)
                pageset[key.strip()] = int(val)
                continue

        if output_line:
            if pageset:
                output_line[zone]['pagesets'].append(pageset)

            raw_output.append(output_line)

    return raw_output if raw else _process(raw_output)

